import{_ as t,o as e,c as i,a6 as l}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"回望：从 mini 到真实 Clash","description":"","frontmatter":{"title":"回望：从 mini 到真实 Clash"},"headers":[],"relativePath":"mini-clash-course/12-review-vs-real.md","filePath":"mini-clash-course/docs/12-review-vs-real.md"}'),r={name:"mini-clash-course/12-review-vs-real.md"};function d(h,a,o,s,n,c){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="回望-从-mini-到真实-clash" tabindex="-1">回望：从 mini 到真实 Clash <a class="header-anchor" href="#回望-从-mini-到真实-clash" aria-label="Permalink to &quot;回望：从 mini 到真实 Clash&quot;">​</a></h1><h2 id="_12-1-开章-装过-和写过" tabindex="-1">12.1 开章：装过，和写过 <a class="header-anchor" href="#_12-1-开章-装过-和写过" aria-label="Permalink to &quot;12.1 开章：装过，和写过&quot;">​</a></h2><p>第 11 章末尾留了最后一件事：mini 与真实 Clash 差在哪，还有全书开场那个问题的正式收口。都在这一章。</p><p>12 章之前，你大概装过 Clash：点开开关，看面板里 url-test 组自动跳到延迟最低的节点，规则列表一眼扫到底。每个字都认识，连起来不知道在干什么——那种状态叫装过但不懂。现在再打开同一个面板，看见的东西不一样了：select 是你第 10 章写过的组策略，MATCH 是你第 7 章亲手排过顺序的兜底规则，面板上的「延迟」是你掐表到首字节量出来的那个数。<strong>装过与写过之间，隔着这 11 章里你亲手写过的每一个承重件。</strong></p><p>这一章对齐三笔账。第一笔，全书开场的问题——「打开 Clash 之后，流量到底经历了什么」——用你造过的零件正式收口（12.2）。第二笔，全书的词摊开对账，让你自查哪些概念真的进了手（12.3）。第三笔，一张差异地图：真实 Clash 还多什么、每一样差在哪（12.4）——mini 对真实行为的每处简化都在正文声明过，这张地图只是它们的总目录。</p><h2 id="_12-2-全书的答案-打开-clash-之后-流量经历了什么" tabindex="-1">12.2 全书的答案：打开 Clash 之后，流量经历了什么 <a class="header-anchor" href="#_12-2-全书的答案-打开-clash-之后-流量经历了什么" aria-label="Permalink to &quot;12.2 全书的答案：打开 Clash 之后，流量经历了什么&quot;">​</a></h2><p>第 1 章 1.2 节给过一张三角色草图：入口、分流决策、隧道。那时它们只是三个名词，配一句「后面每一章在造哪个零件」。现在每个名词后面都拖着几十行你写过的代码，答案可以整段说出了。下面这段话就是全书的答案——以你写成的 fake-ip 形态为例，一段你能对外复述的话：</p><blockquote><p>你点开开关，操作系统里多了一块告示牌：本机代理住在 127.0.0.1 的某个房间。守规矩的应用读它，把请求交给入口；不读的照旧直连——这是自愿，不是总闸。要罩住不读告示的应用，得靠 TUN 虚拟网卡把整机流量从路由层收进来。流量进门之前通常先查 DNS：代理不真查，先发一个保留网段的假 IP 应付过去，把真域名记在账上。应用拿假门牌来连接时，入口先把它还原成域名，交给规则引擎按序判决：直连，还是走某条出站；出站名再落到代理组，由组按策略选出此刻的节点。判给节点的连接装进加密隧道：每条连接随机取盐，现场派生子密钥，载荷逐块认证加密，线路上只剩密文。远端中继解开后代它去敲目标站的门——目标看到的敲门人是远端，不是你。应答原路返回，一路解回明文交给浏览器。浏览器自始至终只当自己直连了目标；替它跑腿的每一跳，都是可以打开来看的代码。</p></blockquote><p>把这段话逐句对回你写过的章：</p><ul><li>告示牌与自愿语义——第 1 章，「总闸」直觉的证伪你也亲手做过（1.3）。</li><li>TUN 收口——第 9 章；教学版止步于报文解析实验，完整形态在 12.4.4 的差异地图对账。</li><li>DNS 前哨与账本——第 8 章；真实 Clash 的 DNS 还有别的处理模式，配置段也复杂得多（12.4.6）。</li><li>入口——HTTP 的两种说法（第 2 章）与 SOCKS5（第 3 章）；整机挂的是 SOCKS5（第 11 章）。</li><li>还原、判决、选节点——第 7 章规则引擎加第 10 章代理组；顺序不能换的账在 11.3 算过。</li><li>加密隧道——第 5 章先算清防谁（威胁模型），第 6 章落成盐、密钥派生、长度前缀分块三件套。</li><li>远端代连与应答回路——第 4 章两跳链路，第 11 章端到端总装。</li></ul><p><strong>先讲后对。</strong> 现在合上书（关掉这个页面也算），把那段话凭记忆讲给一个会写代码但没读过本书的人——对着空气讲也行。讲不顺的那一句，就是你该回炉的那一章，对应表就在上面。讲完再跑一遍 <code>cd companion &amp;&amp; npm run demo:mini-clash</code>，对着第二幕的打印逐句指认：第②步的「还原回 localhost」就是那段话里「账本换名」的现场，第三幕两条 curl 就是「直连与隧道」两条出站的现场。指认得出一一对应，这个问题才算真正归你。</p><h2 id="_12-3-概念对账-你手里现在有哪些词" tabindex="-1">12.3 概念对账：你手里现在有哪些词 <a class="header-anchor" href="#_12-3-概念对账-你手里现在有哪些词" aria-label="Permalink to &quot;12.3 概念对账：你手里现在有哪些词&quot;">​</a></h2><p>全书主线概念按章回收成一张表。用法：遮住最右列自问；答不出的行，按章号回查。五分钟过一遍，比重读全书便宜得多。</p><table tabindex="0"><thead><tr><th>章</th><th>主线概念</th><th>自检：你能一句话说清吗</th></tr></thead><tbody><tr><td>1</td><td>正向代理、系统代理、socket、TCP 连接、端口、回环地址、字节流</td><td>同一个开关，浏览器见效、命令行纹丝不动，为什么？</td></tr><tr><td>2</td><td>HTTP 报文、请求行、绝对地址形式、CONNECT 隧道</td><td>https:// 过代理为什么必须换 CONNECT，而不是改写请求行？</td></tr><tr><td>3</td><td>SOCKS5、字节协议、大端序、目标地址类型</td><td>客户端一口气发来两步，解析器凭什么不断档？</td></tr><tr><td>4</td><td>两跳链路、中继、帧</td><td>帧头那两字节长度，给字节流补回了什么？</td></tr><tr><td>5</td><td>威胁模型、机密性、完整性、真实性、认证加密、AES-GCM、随机数 nonce</td><td>第二跳上锁防的是谁？防什么、不防什么？</td></tr><tr><td>6</td><td>盐、密钥派生、长度前缀分块</td><td>同 nonce 复用与固定密钥，各会撞上哪场灾难？</td></tr><tr><td>7</td><td>规则引擎、域名后缀规则、网段规则、兜底规则、直连、IP 地址与 CIDR</td><td>规则表的顺序为什么就是优先级？MATCH 放最前会怎样？</td></tr><tr><td>8</td><td>DNS、A 记录、DNS 污染、DNS 泄露、fake-ip</td><td>发一个连不上的假门牌，为什么反而是收益？</td></tr><tr><td>9</td><td>TUN 虚拟网卡、五元组、IP 头部、报文段</td><td>代理进程凭什么把一包一包的字节认回各自的连接？</td></tr><tr><td>10</td><td>声明式配置、代理组、自动测速组、延迟探测</td><td>改一条分流规则，为什么一行代码都不用碰？</td></tr><tr><td>11</td><td>端到端、接缝</td><td>还原与判决的顺序为什么不能换？</td></tr></tbody></table><p>表里还埋着四个你亲手推翻过的直觉：整机流量自动走总闸（第 1 章）、TCP 按消息送达（第 3 章）、加密了就改不了（第 5 章）、DNS 只是查表（第 8 章）。亲手推翻过的直觉不会回来——这是做实验比背结论多赚的部分。</p><h3 id="自查" tabindex="-1">自查 <a class="header-anchor" href="#自查" aria-label="Permalink to &quot;自查&quot;">​</a></h3><ol><li>迁移：同事的机器开着真实 Clash 的 TUN 模式。一个从不读系统代理设置的命令行工具发起 DNS 查询，这个查询会先落到谁手里？为什么说这恰好治好了第 1 章那台「连不上的命令行」？</li><li>证伪：朋友说「反正都加密了，内容就改不了」。用你亲手跑过的两个实验反驳他，再补一句 mini 的隧道不防什么。</li><li>设计：把「假门牌还原」从入口挪到远端中继——远端拿到 198.18.x.x 再查账。这个方案整不了机，说出两个互相独立的原因。</li></ol><details class="details custom-block"><summary>参考答案与锚点</summary><ol><li>先落进 TUN 设备、交给代理进程。TUN 在路由层收口：系统代理罩不住的流量（不读告示的应用、DNS 这类 UDP 查询）照样得从虚拟网卡过。第 1 章那台命令行连不上，是因为它不读告示牌、直连又不通；TUN 之后读不读告示不再重要——这正是 9.3.1「自愿与收口」的差别、9.3.5 里 DNS 接管的义务。</li><li>实验一：第 5 章普通加密的篡改实验——改一个密文字节，解密端若无其事地吐出错位内容，「看不懂」不等于「改不了」。实验二：第 6 章的篡改用例与第 11 章整机上的回归——AEAD 验漆失败即断线，坏字节一个都到不了目标（回查 5.3.4 与 11.4）。不防的：mini 无长度填充，块长与到达时机在线上可见——流量分析不在防线内（回查 6.3.4 的对表与差异清单第 6 章条目）。</li><li>原因一：账本长在入口同进程的 FakeIpPool 里，远端没有账可查（回查 8.4.1）。原因二：就算把账搬过去也晚了——规则判决在入口本地，见不到真域名就判不了直连还是隧道，域名行整体失明，连接只能落 IP 行或兜底（回查 11.3 的反事实与 7.3.5 的决策树）。</li></ol></details><h2 id="_12-4-差异地图-mini-之外-真实-clash-还有什么" tabindex="-1">12.4 差异地图：mini 之外，真实 Clash 还有什么 <a class="header-anchor" href="#_12-4-差异地图-mini-之外-真实-clash-还有什么" aria-label="Permalink to &quot;12.4 差异地图：mini 之外，真实 Clash 还有什么&quot;">​</a></h2><p>写过 mini 再看真实 Clash，差异不是一堆杂项，是七组各说一件事的主题。每组讲清 mini 写到哪、真实的完整形态是什么；逐条明细不在这里重抄——每一处简化都登记在<a href="./divergence.html">差异清单附录</a>里，按章排布，与本节七组对应。真实 Clash 的能力以下按其公开文档的概念写，不引实现。</p><h3 id="_12-4-1-协议支持面-入口与出站" tabindex="-1">12.4.1 协议支持面：入口与出站 <a class="header-anchor" href="#_12-4-1-协议支持面-入口与出站" aria-label="Permalink to &quot;12.4.1 协议支持面：入口与出站&quot;">​</a></h3><p>mini 的入口协议是你亲写的两种：HTTP 正向代理（第 2 章，absolute-form 与 CONNECT）和 SOCKS5（第 3 章）；整机只挂 SOCKS5 一个口（第 11 章）。出站只有一种节点——带密码的 AEAD 中继（第 4、6 章）。真实 Clash 的 mixed 端口在同一个房间听懂 HTTP 与 SOCKS5 两种话，入站还有带认证等更多形态；出站是一整个家族：Shadowsocks、VMess、Trojan、SOCKS、HTTP 等，每种自带握手与配置项。明细见<a href="./divergence.html">差异清单</a>第 2、3、11 章条目。</p><h3 id="_12-4-2-加密与混淆" tabindex="-1">12.4.2 加密与混淆 <a class="header-anchor" href="#_12-4-2-加密与混淆" aria-label="Permalink to &quot;12.4.2 加密与混淆&quot;">​</a></h3><p>mini 的第二跳只有一种算法（aes-256-gcm）、只跑 TCP、无长度填充——块长与到达时机在线上可见，流量分析不防，第 6 章声明过。真实的加密面宽得多：Shadowsocks 规范本身还有 chacha20 系等 AEAD 方法与 UDP 形态；VMess、Trojan 等协议各自带握手、认证与混淆设计。在真实 Clash 里换一种加密是改一行配置的事；在 mini 里是重写一个模块——mini 的目标是把一种看穿，不是把每种都装上。明细见<a href="./divergence.html">差异清单</a>第 6 章条目。</p><h3 id="_12-4-3-连接复用与-mux" tabindex="-1">12.4.3 连接复用与 mux <a class="header-anchor" href="#_12-4-3-连接复用与-mux" aria-label="Permalink to &quot;12.4.3 连接复用与 mux&quot;">​</a></h3><p>mini 里每条浏览器连接独占一条第二跳连接（第 4 章），HTTP 上游也是每请求新拨一条（第 2 章）——逻辑直白，代价是握手逐条付。真实生态有一组专门省这笔钱的机制：上游连接的池化复用，以及多路复用（mux——把多条连接的流并到一条物理连接上跑，省握手也省等待）。mini 刻意不做：第 4 章要让「一条连接对应一根管子」保持看得见。明细见<a href="./divergence.html">差异清单</a>第 2、4 章条目。</p><h3 id="_12-4-4-真实-tun-栈" tabindex="-1">12.4.4 真实 TUN 栈 <a class="header-anchor" href="#_12-4-4-真实-tun-栈" aria-label="Permalink to &quot;12.4.4 真实 TUN 栈&quot;">​</a></h3><p>第 9 章的 TUN 件止步于读侧：在自造样本上拆 IP 头部与报文段、按五元组把包认回连接——不回话、不重传、不碰设备。真实 TUN 的完整形态是四件套。一，创建 TUN 设备本身；二，改路由表，把默认路由指过去，还得给代理进程自己的出网流量留一条更具体的豁免路由，否则自己发的包又流回自己；三，接管邻居协议与 DNS——ARP 应答（把 IP 换成网卡硬件地址的查询）、DNS 查询全由代理进程出面；四，当一整个协议栈：收到 SYN 要回 SYN|ACK，丢包要重传，校验和、拥塞控制、流量控制一样不能少。这就是第 9 章预告的「完整协议栈义务」。而这份义务没人手写：公开文档里用户态栈是可选的现成件——在用户进程里把操作系统内核干的协议栈活再干一遍的实现，Clash 的 TUN 配置里可以在 gvisor、system 两类之间选。教学版用「样本喂解析器」把四件全部绕开，换来的聚焦是「包怎么变回连接」这一件事。明细见<a href="./divergence.html">差异清单</a>第 9、11 章条目。</p><h3 id="_12-4-5-规则与-providers" tabindex="-1">12.4.5 规则与 providers <a class="header-anchor" href="#_12-4-5-规则与-providers" aria-label="Permalink to &quot;12.4.5 规则与 providers&quot;">​</a></h3><p>mini 的规则表只有五种承重形态（DOMAIN、DOMAIN-SUFFIX、DOMAIN-KEYWORD、IP-CIDR、MATCH），未知类型带行号报错（第 7 章）；表只有一份，长在配置里。真实 Clash 的规则是一整个家族：GEOIP 按地理位置数据库匹配目标 IP，还有按来源 IP、按进程名匹配的行，逻辑规则能把多条规则 AND、OR、NOT 组合；更有 providers 机制——规则表本身可以从远程订阅、整张更新，像节点订阅一样。行为上还有一处相反的取舍：真实 Clash 遇到 IP 行时默认先把域名解析成 IP 去试，no-resolve 可以关掉它；mini 的「有域名先不解析」是第 7 章声明过的教学取舍。明细见<a href="./divergence.html">差异清单</a>第 7 章条目。</p><h3 id="_12-4-6-配置与生态" tabindex="-1">12.4.6 配置与生态 <a class="header-anchor" href="#_12-4-6-配置与生态" aria-label="Permalink to &quot;12.4.6 配置与生态&quot;">​</a></h3><p>mini 用 JSON 教声明式配置的同构语义（第 10 章）；真实 Clash 的配置是 YAML，长得多也细得多：DNS 段能配上游解析器与分流策略，入站能配多种监听形态。代理组家族在 select 与 url-test 之外还有 fallback（节点坏了自动换下家）、load-balance（把连接摊开）、relay（把几个节点串成链）；url-test 自带 interval、tolerance 一类旋钮——mini 的探测是建组时测一轮、全灭回退名单第一个。明细见<a href="./divergence.html">差异清单</a>第 8、10、11 章条目。</p><h3 id="_12-4-7-工程化" tabindex="-1">12.4.7 工程化 <a class="header-anchor" href="#_12-4-7-工程化" aria-label="Permalink to &quot;12.4.7 工程化&quot;">​</a></h3><p>mini 是个教学工程：73 条回环测试、一条 demo 命令、零第三方运行时依赖；select 切换是编程接口，链路不检查 write 返回值（无背压）。真实 Clash 是常驻产品：守护进程、外部控制器（RESTful API）与图形面板、配置热重载、分级日志、多平台构建，外加生产级的并发与内存管理。你在面板上点的那下「切换节点」，走的就是外部控制器那条 API。明细见<a href="./divergence.html">差异清单</a>第 4、10 章条目。</p><p>读差异清单的正确姿势：它不是欠账单。每一条简化都换来了「那一章只教一件事」——顺着附录回查，每条差异都能落回正文里声明它的那一节。差异清单因此是全书的另一张目录：从任何一个差异进去，都能走到教它的那章。</p><h2 id="_12-5-收束-从用户到写过它的人" tabindex="-1">12.5 收束：从用户到写过它的人 <a class="header-anchor" href="#_12-5-收束-从用户到写过它的人" aria-label="Permalink to &quot;12.5 收束：从用户到写过它的人&quot;">​</a></h2><p>回到开篇的面板。url-test 自动跳节点，你看到的是一组掐表到首字节的成绩单；规则列表滚动，你看到的是一张按序首中即停的判决表；托盘图标亮起，你看到的是一块告示牌加一串自愿与收口的语义。面板没变，看面板的人变了。</p><p>对完三笔账：全书开场的问题有了你自己的答案，而且每句都对得上代码（12.2）；全书的词进没进手，一张表查得出来（12.3）；真实 Clash 与 mini 的距离，七组主题说得清（12.4）。回查的家具有三个附录：术语表、字节协议速查表、差异清单。companion 仓还留在你手里——73 条用例全绿只是一个快照，改它、拆它、按测试梯子从红写回绿，都是继续学的路。</p><p>书名那个问题——打开 Clash 之后，流量到底经历了什么——你已经用十二段代码回答过了。</p><blockquote><p>边界说明：代理与隧道技术在不同地区受不同法规约束。本书只讨论协议与工程原理，全部实验都在本机内部完成，不提供任何真实节点信息——请在遵守当地法律法规的前提下学习。</p></blockquote>',40)])])}const u=t(r,[["render",d]]);export{p as __pageData,u as default};
